import time
from collections import OrderedDict
from collections.abc import Callable, Hashable

class TTLCache[K: Hashable, V]:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float] = time.monotonic) -> None:
        if capacity < 0 or ttl <= 0:
            raise ValueError("capacity must be >= 0 and ttl > 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data: OrderedDict[K, tuple[float, V]] = OrderedDict()

    def get(self, key: K, default: V | None = None) -> V | None:
        entry = self._data.get(key)
        if entry is None:
            return default
        expires_at, value = entry
        if self.clock() >= expires_at:
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def put(self, key: K, value: V) -> None:
        if self.capacity == 0:
            return
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = (self.clock() + self.ttl, value)
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def purge(self) -> int:
        now = self.clock()
        expired = [k for k, (expires_at, _) in self._data.items() if now >= expires_at]
        for k in expired:
            del self._data[k]
        return len(expired)

    def __len__(self) -> int:
        return len(self._data)

